mapper.codeEditorJavascript:
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const titles=(input.sheets||[]).map(s=>String((s.properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
for(let k=-1;k<2;k++){const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+k,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(titles.includes(t)) tabs.push(t);}
return {body: JSON.stringify({dataFilters:[{a1Range:"'הקדמה מיידית'!A1:R3000"},{a1Range:"'יעדים'!A2:B80"}].concat(tabs.map(t=>({a1Range:"'"+t+"'!A1:I2000"}))), valueRenderOption:'FORMATTED_VALUE'})};

// RULE (Steve 12/11/2026): customer said "כן" to an advance for tomorrow/Sunday but did not pick time windows within 1 hour -> alert the selling rep once (column R). Never Fri/Sat, 08:00-21:00 only. Do not remove.
const BIDI=new RegExp('[\\s'+String.fromCharCode(8206,8207)+']+','g'); const norm=s=>String(s==null?'':s).replace(BIDI,' ').trim();
const vrs=input.ranges||[];
const rangeOf=vr=>String((vr.valueRange||vr||{}).range||'');
const valsOf=vr=>((vr.valueRange||vr||{}).values)||[];
const log=valsOf(vrs.find(v=>rangeOf(v).includes('הקדמה מיידית'))||{});
const targets=valsOf(vrs.find(v=>rangeOf(v).includes('יעדים'))||{}).filter(r=>r&&norm(r[0]));
const nowIL=input.now?new Date(input.now):new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const dow=nowIL.getDay(), mins=nowIL.getHours()*60+nowIL.getMinutes();
const stamp=nowIL.getDate()+'/'+(nowIL.getMonth()+1)+' '+String(nowIL.getHours()).padStart(2,'0')+':'+String(nowIL.getMinutes()).padStart(2,'0');
const alerts=[];
if(dow<=4&&mins>=8*60&&mins<21*60){
 const toIntl=p=>{let d=String(p||'').replace(/\D/g,''); if(d.startsWith('972')) return d; if(d.startsWith('0')) d=d.slice(1); return d?'972'+d:'';};
 const findRep=rep=>{rep=norm(rep); let m=targets.filter(x=>norm(x[0])===rep); if(!m.length&&rep){const f=rep.split(' ')[0]; m=targets.filter(x=>{const a=norm(x[0]); return a===f||a.split(' ')[0]===f;});} return m[0]||null;};
 log.forEach((r,i)=>{
  if(i===0) return;
  if(norm(r[11])!=='כן'||norm(r[13])!=='שאלון חלונות'||norm(r[14])||norm(r[17])) return;
  const m=norm(r[12]).match(/(\d{1,2})\/(\d{1,2})\s+(\d{1,2}):(\d{2})/); if(!m) return;
  let at=new Date(nowIL.getFullYear(),+m[2]-1,+m[1],+m[3],+m[4]); if(at>nowIL) at.setFullYear(at.getFullYear()-1);
  if((nowIL-at)/60000<60) return;
  if((nowIL-at)/86400000>3) return; // too old, skip
  const rr=findRep(r[5]); const ph=rr?toIntl(rr[1]):''; const first=rr?norm(rr[0]).split(' ')[0]:'';
  const cn=norm(r[4]); const sub=norm(r[10]);
  const msg=(first?'היי '+first+', ':'')+'⏰ לקוח שלך ענה שהוא רוצה להקדים את ההתקנה '+norm(r[8])+', אבל כבר יותר משעה לא בחר חלון שעות.\n\n👤 '+norm(r[2])+(cn?' (לקוח '+cn+')':'')+'\n📱 '+norm(r[3])+'\n\nתתקשר אליו ותסגור חלון שעות, ואז שלח לבוט, למשל: הקדמה '+(cn||'<מספר לקוח>')+' 15/11 10-12'+(sub?'\n\n💬 השיחה עם הלקוח: https://app.manychat.com/fb3981719/chat/'+sub:'');
  alerts.push({row:i+1, body:JSON.stringify({chatId:(ph||'972544604246')+'@c.us', message:(ph?'':'⚠️ לא מצאתי טלפון לנציג "'+norm(r[5])+'" בלשונית יעדים:\n\n')+msg}), mark:JSON.stringify({valueInputOption:'RAW',data:[{range:"'הקדמה מיידית'!R"+(i+1),values:[['נשלחה '+stamp]]}]})});
 });
}
return {count:alerts.length, alerts};

// RULE (Steve 12/11/2026): when an advance the CUSTOMER asked for (data store source = לקוח) is approved, send the customer a WhatsApp confirmation (ManyChat flow "Advance approved - customer msg", field adv_confirm_msg) with the new date/window from the דוח מכר. Do not remove.
const BIDI=new RegExp('[\\s'+String.fromCharCode(8206,8207)+']+','g'); const norm=s=>String(s==null?'':s).replace(BIDI,' ').trim();
const HM=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const DAYS=['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];
const vrs=input.ranges||[];
const rangeOf=vr=>String((vr.valueRange||vr||{}).range||'');
const valsOf=vr=>((vr.valueRange||vr||{}).values)||[];
const cn=norm(input.cn).replace(/\D/g,'');
let sub='', first='';
const log=valsOf(vrs.find(v=>rangeOf(v).includes('הקדמה מיידית'))||{});
for(let i=log.length-1;i>=1;i--){ if(norm(log[i][4]).replace(/\D/g,'')===cn){ sub=norm(log[i][10]); first=norm(log[i][2]).split(' ')[0]; break; } }
// RULE (15/11/2026, כפילויות): לקוח יכול להופיע בכמה שורות בדוח המכר (שורה בלי מספר לקוח / תאריך ישן). לוקחים את השורה שהתאריך בה = התאריך שאושר, אחרת האחרונה עם תאריך; שורה ריקה לא דורסת. אם אין שורה בלוג עם מספר הלקוח - מחפשים את המנוי בלוג לפי הטלפון מהדוח. Do not remove.
const l9=s=>{const d=String(s||'').replace(/\D/g,'');return d.length>=9?d.slice(-9):'';};
const gOf=r=>norm(r[6]).replace(/\D/g,'');
const rep=[];
for(const vr of vrs){ const rg=rangeOf(vr); if(rg.includes('הקדמה מיידית')||rg.includes('יעדים')) continue; for(const r of valsOf(vr).slice(1)) rep.push(r||[]); }
const byNum=cn?rep.filter(r=>gOf(r)===cn):[];
const logHit=!!cn&&log.some((r,i)=>i>=1&&norm(r[4]).replace(/\D/g,'')===cn);
const phs=new Set(byNum.map(r=>l9(r[3])).filter(Boolean));
if(cn) for(let i=1;i<log.length;i++){ if(norm(log[i][4]).replace(/\D/g,'')===cn&&l9(log[i][3])) phs.add(l9(log[i][3])); }
const mine=cn?rep.filter(r=>byNum.includes(r)||(phs.has(l9(r[3]))&&(!gOf(r)||gOf(r)===cn))):[];
const want=parseD(input.new_date)||parseD(input.short_date);
let pick=null;
if(want) for(const r of mine){ const d=parseD(norm(r[4])); if(d&&d.getTime()===want.getTime()) pick=r; }
if(!pick) for(const r of mine) if(norm(r[4])) pick=r;
if(!pick&&byNum.length) pick=byNum[byNum.length-1];
let E=pick?norm(pick[4]):'',F=pick?norm(pick[5]):'';
if(cn&&!logHit){ const rp=new Set(mine.map(r=>l9(r[3])).filter(Boolean)); for(let i=log.length-1;i>=1;i--){ const g=norm(log[i][4]).replace(/\D/g,''); if((!g||g===cn)&&rp.has(l9(log[i][3]))){ sub=norm(log[i][10]); first=norm(log[i][2]).split(' ')[0]; break; } } }
function parseD(s){ s=String(s||''); let m=s.match(/(\d{1,2})\s+(\S+)\s+(\d{4})/); if(m){const mi=HM.indexOf(m[2]); if(mi>=0) return new Date(+m[3],mi,+m[1]);} m=s.match(/(\d{4})-(\d{1,2})-(\d{1,2})/); if(m) return new Date(+m[1],+m[2]-1,+m[3]); m=s.match(/(\d{1,2})[\/.](\d{1,2})[\/.](\d{2,4})/); if(m){let y=+m[3]; if(y<100)y+=2000; return new Date(y,+m[2]-1,+m[1]);} return null; }
const d=parseD(E)||parseD(input.new_date)||parseD(input.short_date);
const dateText=d?'יום '+DAYS[d.getDay()]+' '+d.getDate()+'/'+(d.getMonth()+1):norm(input.new_date);
const slotRaw=F||norm(input.new_slot);
const wins=[...slotRaw.matchAll(/(\d{1,2}):?(\d{2})?\s*-\s*(\d{1,2}):?(\d{2})?/g)].map(m=>[+m[1],+m[3]]).sort((a,b)=>a[0]-b[0]);
const pad=n=>String(n).padStart(2,'0')+':00';
let slotText='';
if(/כל היום/.test(slotRaw)||!wins.length) slotText='במהלך היום';
else{ let contiguous=true; for(let i=1;i<wins.length;i++) if(wins[i][0]!==wins[i-1][1]) contiguous=false;
 slotText=contiguous?'בין השעות '+pad(wins[0][0])+' ל-'+pad(wins[wins.length-1][1]):'באחד מהחלונות: '+wins.map(w=>pad(w[0])+'-'+pad(w[1])).join(' / '); }
// RULE (Steve 12/11/2026): never mention יהל תקשורת to customers - we are yes. Message = approved template advance_approved_customer: היי {tpl_cust_name} ... הוקדמה ל{adv_confirm_msg}.
const msg=dateText+', '+slotText;
const repFail=JSON.stringify({chatId:norm(input.rep_chat)||'972544604246@c.us', message:'⚠️ ההקדמה של '+norm(input.name)+' (לקוח '+cn+') אושרה, אבל לא הצלחתי לשלוח לו הודעת אישור בוואטסאפ. תעדכן אותו בבקשה: הוקדם ל'+dateText+', '+slotText+'.'});
return {sub, ok:/^\d+$/.test(sub), msg, first:first||'', repFail};
